        Role: "mayor" | "community_councillor" | "housing_officer" | "admin";
        /** @enum {string} */
        HousingRole: "admin" | "manager" | "analyst" | "viewer";
        /** @enum {string} */
        AccountStatus: "active" | "inactive";
        /** @enum {string} */
        MunicipalityStatus: "active" | "inactive";
        /** @enum {string} */
        Mandate: "mayor" | "deputy_mayor" | "municipal_councillor" | "community_councillor";
        /** @enum {string} */
        IndicatorFamily: "price" | "dpe" | "risk";
        /** @enum {string} */
        GridLevel: "municipality" | "district" | "street";
        /** @enum {string} */
        QualityStatus: "available" | "missing" | "insufficient_sample" | "suppressed" | "source_error" | "not_computable";
        /** @enum {string} */
        DistrictType: "municipal" | "iris";
        /** @enum {string} */
        BenchmarkLevel: "municipality" | "agglomeration" | "department_excl_agglo";
        /** @enum {string} */
        ReportStatus: "published" | "withdrawn" | "replaced";
        /** @enum {string} */
        Visibility: "internal" | "public";
        /** @enum {string} */
        RequestStatus: "new" | "in_progress" | "awaiting_details" | "answered" | "closed";
        /** @enum {string} */
        QualityCode: "ok" | "to_verify" | "estimated" | "missing";
        /** @enum {string} */
        JobStatus: "queued" | "running" | "failed" | "ready";
        /** @enum {string} */
        DivisionType: "municipal" | "iris";
        /** @enum {string} */
        CoverageStatus: "covered" | "not_covered";
        /** @enum {string} */
        RiskFamily: "clay" | "flood" | "groundwater" | "ground_movement" | "cavity" | "technological";
